    sort(command) {
      this.sortOption = command;
    },
    sortData(data) {
      // 文件夹始终在前
      const folders = data.filter(file => file.isFolder);
      const files = data.filter(file => !file.isFolder);
      switch (this.sortOption) {
        case "dateAsc":
          // 按时间升序
          folders.sort((a, b) => new Date(a.metadata?.TimeStamp) - new Date(b.metadata?.TimeStamp));
          files.sort((a, b) => new Date(a.metadata?.TimeStamp) - new Date(b.metadata?.TimeStamp));
          break;
        case "nameAsc":
          // 按文件名升序
          folders.sort((a, b) => a.name.localeCompare(b.name));
          files.sort((a, b) => a.name.localeCompare(b.name));
          break;
        case "nameDesc":
          // 按文件名降序
          folders.sort((a, b) => b.name.localeCompare(a.name));
          files.sort((a, b) => b.name.localeCompare(a.name));
          break;
        case "dateDesc":
        default:
          // 按时间降序
          folders.sort((a, b) => new Date(b.metadata?.TimeStamp) - new Date(a.metadata?.TimeStamp));
          files.sort((a, b) => new Date(b.metadata?.TimeStamp) - new Date(a.metadata?.TimeStamp));
          break;
      }
      return folders.concat(files);
    },
