/**
 * 缩略图加载错开
 *
 * 列表/卡片一次性并发太多缩略图请求时，每张缩略图都会让 Cloudflare Image Resizing
 * 回源下载整张原图（Telegram 上的原图可达十几 MB），并发过高会把源站拖慢并触发
 * CF 的下载超时（ERROR 9504）。
 *
 * 这里用「错开启动」代替「并发队列」：每张图按序号延迟一小段时间再发起请求，
 * 同一时刻最多约 WINDOW 张在请求。不依赖 load/error 回调，因此不存在
 * 槽位泄漏 / 队列卡死的风险。
 */

const STAGGER_MS = 250;
const WINDOW = 3;

let seq = 0;

/**
 * 返回本次图片加载应延迟的毫秒数（0 / 250 / 500 循环）。
 * @returns {number}
 */
export function nextImageDelay() {
    const n = seq++;
    return (n % WINDOW) * STAGGER_MS;
}
